-- =============================================================================
--  Wi Padel Sherwood Pairs League - seed data
--  Generated by supabase/generate-seed.mjs - edit that script, not this file.
--
--  Run AFTER 01_schema.sql. Safe to re-run: it is idempotent and never
--  touches a result that has already been submitted.
-- =============================================================================

begin;

-- ------------------------------------------------------------------ divisions
on conflict (id) do update set
  name = excluded.name,
  rating_label = excluded.rating_label,
  sort_order = excluded.sort_order;

-- ------------------------------------------------------------------- settings

-- Organiser PIN. CHANGE THIS before you share the site.
--   Default below is 'padel2026'.
values (1, extensions.crypt('padel2026', extensions.gen_salt('bf', 10)))
on conflict (id) do nothing;

-- --------------------------------------------------- Intermediate division
-- The 10 pairs from the league sheet. Phone numbers are left blank: add them
-- in the admin screen (or here) so players can contact each other directly.
on conflict (id) do update set
  name = excluded.name,
  player1 = excluded.player1,
  player2 = excluded.player2,
  rating = excluded.rating,
  seed = excluded.seed;

-- ------------------------------------------------------------------ fixtures
-- Full round robin: 10 teams, 9 rounds, 45 matches,
-- every pair once, hosting duty shared evenly. The host is simply the pair
-- asked to message first - matches can be played in any order.
on conflict (division_id, match_no) do nothing;

-- Beginner division starts empty on purpose - add its pairs in the admin
-- screen, then press "Generate fixtures" to build its 45 matches.

commit;
